CREATE TABLE ${primehrSchema}.rr_award_cycle(id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,title VARCHAR(200) NOT NULL,description VARCHAR(2000),policy_version_id VARCHAR(36) NOT NULL,policy_definition_version INT NOT NULL,policy_fingerprint VARCHAR(64) NOT NULL,nomination_opens_on DATE NOT NULL,nomination_closes_on DATE NOT NULL,evaluation_opens_on DATE NOT NULL,evaluation_closes_on DATE NOT NULL,decision_due_on DATE NOT NULL,conferment_on DATE,status VARCHAR(20) NOT NULL,opened_by VARCHAR(100),opened_at DATETIMEOFFSET,closed_by VARCHAR(100),closed_at DATETIMEOFFSET,transition_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_rr_cycle_policy FOREIGN KEY(policy_version_id) REFERENCES ${primehrSchema}.rr_governance_policy_version(id),CONSTRAINT uk_rr_cycle_code UNIQUE(agency_id,normalized_code),CONSTRAINT ck_rr_cycle_policy_version CHECK(policy_definition_version>=1),CONSTRAINT ck_rr_cycle_status CHECK(status IN('DRAFT','OPEN','CLOSED','CANCELLED')),CONSTRAINT ck_rr_cycle_windows CHECK(nomination_closes_on>=nomination_opens_on AND evaluation_opens_on>=nomination_closes_on AND evaluation_closes_on>=evaluation_opens_on AND decision_due_on>=evaluation_closes_on AND (conferment_on IS NULL OR conferment_on>=decision_due_on)));
CREATE INDEX ix_rr_cycle_window ON ${primehrSchema}.rr_award_cycle(agency_id,status,nomination_opens_on,nomination_closes_on);
CREATE TABLE ${primehrSchema}.rr_nomination(id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,cycle_id VARCHAR(36) NOT NULL,category_version_id VARCHAR(36) NOT NULL,category_definition_version INT NOT NULL,category_fingerprint VARCHAR(64) NOT NULL,nominee_type VARCHAR(30) NOT NULL,nominator_employee_id BIGINT NOT NULL,nominator_employee_no VARCHAR(100) NOT NULL,nominator_name VARCHAR(300) NOT NULL,nominator_appointment_id BIGINT NOT NULL,nominator_business_unit_id BIGINT,nominator_fingerprint VARCHAR(64) NOT NULL,individual_employee_id BIGINT,individual_employee_no VARCHAR(100),individual_name VARCHAR(300),individual_appointment_id BIGINT,individual_business_unit_id BIGINT,individual_fingerprint VARCHAR(64),group_name VARCHAR(300),organization_type VARCHAR(30),organization_id BIGINT,organization_code VARCHAR(100),organization_name VARCHAR(300),organization_fingerprint VARCHAR(64),contribution_narrative VARCHAR(8000) NOT NULL,committee_narrative VARCHAR(8000),publication_narrative VARCHAR(4000),status VARCHAR(20) NOT NULL,content_revision INT NOT NULL,submitted_by VARCHAR(100),submitted_at DATETIMEOFFSET,submission_fingerprint VARCHAR(64),withdrawn_by VARCHAR(100),withdrawn_at DATETIMEOFFSET,withdrawal_reason VARCHAR(2000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_rr_nomination_cycle FOREIGN KEY(cycle_id) REFERENCES ${primehrSchema}.rr_award_cycle(id),CONSTRAINT fk_rr_nomination_category FOREIGN KEY(category_version_id) REFERENCES ${primehrSchema}.rr_award_category_version(id),CONSTRAINT ck_rr_nomination_category_version CHECK(category_definition_version>=1),CONSTRAINT ck_rr_nomination_type CHECK(nominee_type IN('INDIVIDUAL','GROUP','ORGANIZATION_UNIT')),CONSTRAINT ck_rr_nomination_status CHECK(status IN('DRAFT','SUBMITTED','WITHDRAWN')),CONSTRAINT ck_rr_nomination_subject CHECK((nominee_type='INDIVIDUAL' AND individual_employee_id IS NOT NULL AND group_name IS NULL AND organization_id IS NULL) OR (nominee_type='GROUP' AND individual_employee_id IS NULL AND group_name IS NOT NULL AND organization_id IS NULL) OR (nominee_type='ORGANIZATION_UNIT' AND individual_employee_id IS NULL AND group_name IS NULL AND organization_id IS NOT NULL)));
CREATE INDEX ix_rr_nomination_cycle ON ${primehrSchema}.rr_nomination(agency_id,cycle_id,status);CREATE INDEX ix_rr_nomination_owner ON ${primehrSchema}.rr_nomination(agency_id,nominator_employee_no,status);
CREATE TABLE ${primehrSchema}.rr_nomination_member(id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,nomination_id VARCHAR(36) NOT NULL,employee_id BIGINT NOT NULL,employee_no VARCHAR(100) NOT NULL,employee_name VARCHAR(300) NOT NULL,appointment_id BIGINT NOT NULL,business_unit_id BIGINT,source_fingerprint VARCHAR(64) NOT NULL,display_order INT NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_rr_nomination_member FOREIGN KEY(nomination_id) REFERENCES ${primehrSchema}.rr_nomination(id),CONSTRAINT uk_rr_nomination_member UNIQUE(agency_id,nomination_id,employee_no),CONSTRAINT ck_rr_nomination_member_order CHECK(display_order>=1));
CREATE INDEX ix_rr_nomination_member_nomination ON ${primehrSchema}.rr_nomination_member(agency_id,nomination_id,display_order);
CREATE TABLE ${primehrSchema}.rr_nomination_source(id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,nomination_id VARCHAR(36) NOT NULL,source_type VARCHAR(30) NOT NULL,source_id VARCHAR(36) NOT NULL,source_version BIGINT NOT NULL,source_fingerprint VARCHAR(64) NOT NULL,source_label VARCHAR(500) NOT NULL,source_changed_at DATETIMEOFFSET,captured_at DATETIMEOFFSET NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_rr_nomination_source FOREIGN KEY(nomination_id) REFERENCES ${primehrSchema}.rr_nomination(id),CONSTRAINT uk_rr_nomination_source UNIQUE(agency_id,nomination_id,source_type,source_id),CONSTRAINT ck_rr_nomination_source_type CHECK(source_type IN('COMPETENCY_PROFILE','PERFORMANCE_OUTCOME','LD_COMPLETION')),CONSTRAINT ck_rr_nomination_source_version CHECK(source_version>=0));
CREATE INDEX ix_rr_nomination_source_nomination ON ${primehrSchema}.rr_nomination_source(agency_id,nomination_id);
CREATE TABLE ${primehrSchema}.rr_nomination_evidence(id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,nomination_id VARCHAR(36) NOT NULL,title VARCHAR(200) NOT NULL,original_filename VARCHAR(255) NOT NULL,storage_provider VARCHAR(30) NOT NULL,storage_object_key VARCHAR(500) NOT NULL,media_type VARCHAR(120) NOT NULL,byte_size BIGINT NOT NULL,checksum VARCHAR(64) NOT NULL,visibility VARCHAR(30) NOT NULL,uploaded_by VARCHAR(100) NOT NULL,uploaded_at DATETIMEOFFSET NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_rr_nomination_evidence FOREIGN KEY(nomination_id) REFERENCES ${primehrSchema}.rr_nomination(id),CONSTRAINT ck_rr_nomination_evidence_size CHECK(byte_size>0),CONSTRAINT ck_rr_nomination_evidence_visibility CHECK(visibility IN('NOMINEE_VISIBLE','COMMITTEE_RESTRICTED','PUBLICATION_SAFE')));
CREATE INDEX ix_rr_nomination_evidence_nomination ON ${primehrSchema}.rr_nomination_evidence(agency_id,nomination_id,uploaded_at);
